begin;insert into public.security_permissions(codigo,modulo,nome,criticidade)values('esocial.read','integracoes','Consultar eSocial','sensivel'),('esocial.manage','integracoes','Gerenciar fila eSocial','critica')on conflict(codigo)do update set nome=excluded.nome;insert into public.security_role_permissions(role_id,permission_id)select r.id,p.id from public.security_roles r join public.security_permissions p on p.codigo in('esocial.read','esocial.manage')where r.codigo='tenant_admin'on conflict do nothing;create table public.esocial_certificates(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),certificate_type text not null,subject_name text not null,serial_number text not null,valid_from timestamptz not null,valid_to timestamptz not null,secret_reference text not null,active boolean default true,check(certificate_type in('A1','A3')),unique(tenant_id,serial_number));create table public.esocial_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),event_type text not null,external_id text not null,payload_xml text not null,payload_sha256 text not null,status text not null default'pendente',attempts int not null default 0,next_attempt_at timestamptz default now(),protocol text,receipt text,last_error text,created_by uuid references public.profiles(id),created_at timestamptz default now(),updated_at timestamptz default now(),check(payload_sha256~'^[0-9a-f]{64}$'),check(status in('pendente','validado','assinado','transmitindo','aceito','rejeitado','erro')),unique(tenant_id,external_id));create table public.esocial_event_attempts(id bigint generated always as identity primary key,tenant_id uuid not null references public.tenants(id),event_id uuid not null references public.esocial_events(id),attempt_number int not null,request_sha256 text,response_code text,response_excerpt text,occurred_at timestamptz default now(),unique(event_id,attempt_number));alter table public.esocial_certificates enable row level security;alter table public.esocial_events enable row level security;alter table public.esocial_event_attempts enable row level security;do $$begin if to_regnamespace('auth')is not null then create policy esocial_certs on public.esocial_certificates for all to authenticated using(private.has_tenant_permission(tenant_id,'esocial.read'))with check(private.has_tenant_permission(tenant_id,'esocial.manage'));create policy esocial_events on public.esocial_events for all to authenticated using(private.has_tenant_permission(tenant_id,'esocial.read'))with check(private.has_tenant_permission(tenant_id,'esocial.manage'));create policy esocial_attempts on public.esocial_event_attempts for all to authenticated using(private.has_tenant_permission(tenant_id,'esocial.read'))with check(private.has_tenant_permission(tenant_id,'esocial.manage'));end if;end$$;revoke all on public.esocial_certificates,public.esocial_events,public.esocial_event_attempts from anon;do $$begin if exists(select 1 from pg_roles where rolname='authenticated')then grant select,insert,update on public.esocial_certificates,public.esocial_events,public.esocial_event_attempts to authenticated;grant usage,select on sequence public.esocial_event_attempts_id_seq to authenticated;end if;end$$;commit;
